import json,glob
def scan_all(kws,n=4):
    out=[]
    for fn in sorted(glob.glob('articles/2026/03/*/articles.jsonl')):
        for line in open(fn):
            try:a=json.loads(line)
            except:continue
            t=a.get('title') or ''; c=a.get('content') or ''
            tl=t.lower()
            if any(k in tl for k in kws):
                out.append((a.get('date_publish') or '',t,c))
    seen=set();res=[]
    for d,t,c in out:
        if t not in seen:
            seen.add(t);res.append((d,t,c))
    return res[:n]
